import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';
import {
  AlertTriangle,
  CheckCircle2,
  Download,
  Package,
  Pencil,
  Plus,
  Search,
  SlidersHorizontal,
  Trash2,
  XCircle,
} from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Badge, EmptyState, Modal, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Product } from '../lib/mock';

const emojiChoices = ['🍎', '🍌', '🥦', '🍅', '🥛', '🥚', '🍶', '🥖', '🥐', '🍗', '🐟', '🍚', '🍝', '🧃', '🥤', '🍪', '🍟', '🧴', '🍇', '🥕', '🧀', '🍫'];

const emptyProduct = (): Product => ({
  id: `p${Date.now()}`,
  name: '',
  sku: '',
  categoryId: 'fruit',
  price: 0,
  oldPrice: undefined,
  unit: 'dona',
  stock: 0,
  emoji: '🍎',
  gradient: 'from-emerald-100 to-emerald-50 dark:from-emerald-500/20 dark:to-emerald-500/5',
  description: '',
  active: true,
  sold: 0,
  rating: 4.5,
});

export const Products = () => {
  const { t } = useTranslation();
  const { products, categories, saveProduct, deleteProduct, notify } = useAdmin();
  const [params] = useSearchParams();
  const [query, setQuery] = useState(params.get('q') ?? '');
  const [category, setCategory] = useState('all');
  const [status, setStatus] = useState('all');
  const [sort, setSort] = useState('name');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Product | null>(null);
  const [draft, setDraft] = useState<Product>(emptyProduct());
  const [toDelete, setToDelete] = useState<Product | null>(null);

  const filtered = useMemo(() => {
    let list = [...products];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((p) => `${p.name} ${p.sku}`.toLowerCase().includes(q));
    if (category !== 'all') list = list.filter((p) => p.categoryId === category);
    if (status === 'active') list = list.filter((p) => p.active);
    if (status === 'inactive') list = list.filter((p) => !p.active);
    if (status === 'low') list = list.filter((p) => p.stock > 0 && p.stock <= 10);
    if (status === 'out') list = list.filter((p) => p.stock === 0);
    list.sort((a, b) => {
      if (sort === 'price') return b.price - a.price;
      if (sort === 'stock') return a.stock - b.stock;
      if (sort === 'sold') return b.sold - a.sold;
      return a.name.localeCompare(b.name);
    });
    return list;
  }, [products, query, category, status, sort]);

  const inventoryValue = products.reduce((s, p) => s + p.price * p.stock, 0);

  const openCreate = () => {
    setEditing(null);
    setDraft(emptyProduct());
    setModalOpen(true);
  };

  const openEdit = (product: Product) => {
    setEditing(product);
    setDraft({ ...product });
    setModalOpen(true);
  };

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.name.trim() || draft.price <= 0) {
      notify('Nomi va narxni to\'ldiring', 'error');
      return;
    }
    saveProduct({ ...draft, sku: draft.sku || `SKU-${Math.floor(Math.random() * 9000 + 1000)}` });
    notify(editing ? t('updated') : t('created'));
    setModalOpen(false);
  };

  const confirmDelete = () => {
    if (!toDelete) return;
    deleteProduct(toDelete.id);
    notify(t('deleted'));
    setToDelete(null);
  };

  const exportCsv = () => {
    const rows = [
      ['SKU', 'Name', 'Category', 'Price', 'Stock', 'Status'],
      ...filtered.map((p) => [p.sku, p.name, categories.find((c) => c.id === p.categoryId)?.name ?? '', String(p.price), String(p.stock), p.active ? 'active' : 'inactive']),
    ];
    const csv = rows.map((r) => r.map((v) => `"${v.replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'maxshop-products.csv';
    a.click();
    URL.revokeObjectURL(url);
    notify('CSV yuklab olindi', 'info');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('productsTitle')}
        subtitle={t('productsSubtitle')}
        action={
          <>
            <button className="btn-secondary btn-sm hidden sm:inline-flex" onClick={exportCsv}>
              <Download size={15} /> {t('export')}
            </button>
            <button className="btn-primary btn-sm" onClick={openCreate}>
              <Plus size={16} /> {t('addProduct')}
            </button>
          </>
        }
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label={t('totalProducts')} value={String(products.length)} icon={<Package size={20} />} />
        <StatCard label={t('inStock')} value={String(products.filter((p) => p.stock > 10).length)} icon={<CheckCircle2 size={20} />} tone="sky" />
        <StatCard label={t('lowStock')} value={String(products.filter((p) => p.stock > 0 && p.stock <= 10).length)} icon={<AlertTriangle size={20} />} tone="amber" />
        <StatCard label={t('inventoryValue')} value={formatUZS(inventoryValue)} icon={<XCircle size={20} />} tone="violet" />
      </div>

      <div className="card p-4 sm:p-5">
        <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center">
          <div className="relative flex-1">
            <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Mahsulot nomi yoki SKU..."
              className="input pl-10"
            />
          </div>
          <div className="grid grid-cols-2 gap-2 sm:flex sm:flex-wrap">
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="select h-[42px] min-w-[140px]">
              <option value="all">{t('all')} kategoriya</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
            <select value={status} onChange={(e) => setStatus(e.target.value)} className="select h-[42px] min-w-[120px]">
              <option value="all">{t('all')}</option>
              <option value="active">{t('active')}</option>
              <option value="inactive">{t('inactive')}</option>
              <option value="low">{t('lowStock')}</option>
              <option value="out">{t('outOfStock')}</option>
            </select>
            <select value={sort} onChange={(e) => setSort(e.target.value)} className="select h-[42px] min-w-[130px]">
              <option value="name">Nomi bo'yicha</option>
              <option value="price">Narx bo'yicha</option>
              <option value="stock">Zaxira bo'yicha</option>
              <option value="sold">Sotuv bo'yicha</option>
            </select>
            <button className="icon-btn h-[42px] w-[42px]" onClick={() => { setQuery(''); setCategory('all'); setStatus('all'); setSort('name'); }} title={t('reset')}>
              <SlidersHorizontal size={16} />
            </button>
          </div>
        </div>

        {filtered.length === 0 ? (
          <EmptyState title={t('noData')} description="Filtrlarni o'zgartiring yoki yangi mahsulot qo'shing." />
        ) : (
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>{t('product')}</th>
                  <th>{t('category')}</th>
                  <th>{t('price')}</th>
                  <th>{t('stock')}</th>
                  <th>Sotuv</th>
                  <th>{t('status')}</th>
                  <th className="text-right">{t('actions')}</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((p) => {
                  const cat = categories.find((c) => c.id === p.categoryId);
                  const stockTone = p.stock === 0 ? 'danger' : p.stock <= 10 ? 'warning' : 'success';
                  return (
                    <tr key={p.id}>
                      <td>
                        <div className="flex items-center gap-3">
                          <span className={cn('flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br text-xl', p.gradient)}>{p.emoji}</span>
                          <div className="min-w-0">
                            <p className="truncate text-xs font-extrabold">{p.name}</p>
                            <p className="text-[10px] font-semibold text-[var(--muted)]">{p.sku} · {p.unit}</p>
                          </div>
                        </div>
                      </td>
                      <td>
                        <Badge tone="neutral">{cat?.icon} {cat?.name}</Badge>
                      </td>
                      <td>
                        <p className="text-xs font-extrabold">{formatUZS(p.price)}</p>
                        {p.oldPrice && <p className="text-[10px] text-[var(--muted)] line-through">{formatUZS(p.oldPrice)}</p>}
                      </td>
                      <td className="w-32">
                        <div className="flex items-center gap-2">
                          <Progress value={(p.stock / 200) * 100} tone={p.stock === 0 ? 'rose' : p.stock <= 10 ? 'amber' : 'brand'} />
                          <span className={cn('shrink-0 text-[10px] font-extrabold', p.stock === 0 ? 'text-rose-500' : p.stock <= 10 ? 'text-amber-500' : 'text-[var(--muted)]')}>
                            {p.stock}
                          </span>
                        </div>
                        <div className="mt-1">
                          <Badge tone={stockTone}>{p.stock === 0 ? t('outOfStock') : p.stock <= 10 ? t('lowStock') : t('inStock')}</Badge>
                        </div>
                      </td>
                      <td className="text-xs font-bold text-[var(--muted)]">{p.sold} ta</td>
                      <td>
                        <Badge tone={p.active ? 'success' : 'neutral'}>{p.active ? t('active') : t('inactive')}</Badge>
                      </td>
                      <td>
                        <div className="flex items-center justify-end gap-1">
                          <button className="icon-btn h-8 w-8" onClick={() => openEdit(p)} title={t('edit')}>
                            <Pencil size={14} />
                          </button>
                          <button className="icon-btn h-8 w-8 text-rose-500 hover:text-rose-600" onClick={() => setToDelete(p)} title={t('delete')}>
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
        <div className="mt-4 flex items-center justify-between text-xs font-semibold text-[var(--muted)]">
          <span>{filtered.length} / {products.length} mahsulot</span>
          <span>Oxirgi yangilanish: bugun 09:42</span>
        </div>
      </div>

      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title={editing ? t('editProduct') : t('addProduct')}
        subtitle="Ma'lumotlarni to'ldiring va saqlang"
        wide
      >
        <form onSubmit={submit} className="space-y-4">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <div>
              <label className="label">{t('name')}</label>
              <input className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Masalan: Qizil olma" />
            </div>
            <div>
              <label className="label">{t('sku')}</label>
              <input className="input" value={draft.sku} onChange={(e) => setDraft({ ...draft, sku: e.target.value })} placeholder="FR-001" />
            </div>
            <div>
              <label className="label">{t('category')}</label>
              <select className="select" value={draft.categoryId} onChange={(e) => setDraft({ ...draft, categoryId: e.target.value })}>
                {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div>
              <label className="label">{t('unit')}</label>
              <select className="select" value={draft.unit} onChange={(e) => setDraft({ ...draft, unit: e.target.value })}>
                <option value="dona">dona</option>
                <option value="kg">kg</option>
                <option value="litr">litr</option>
                <option value="paket">paket</option>
              </select>
            </div>
            <div>
              <label className="label">{t('price')} (so'm)</label>
              <input type="number" className="input" value={draft.price || ''} onChange={(e) => setDraft({ ...draft, price: Number(e.target.value) })} />
            </div>
            <div>
              <label className="label">{t('oldPrice')} (so'm)</label>
              <input type="number" className="input" value={draft.oldPrice || ''} onChange={(e) => setDraft({ ...draft, oldPrice: Number(e.target.value) || undefined })} />
            </div>
            <div>
              <label className="label">{t('stock')}</label>
              <input type="number" className="input" value={draft.stock} onChange={(e) => setDraft({ ...draft, stock: Number(e.target.value) })} />
            </div>
            <div>
              <label className="label">{t('status')}</label>
              <select className="select" value={draft.active ? 'active' : 'inactive'} onChange={(e) => setDraft({ ...draft, active: e.target.value === 'active' })}>
                <option value="active">{t('active')}</option>
                <option value="inactive">{t('inactive')}</option>
              </select>
            </div>
          </div>

          <div>
            <label className="label">Rasm (emoji tanlang)</label>
            <div className="flex flex-wrap gap-1.5">
              {emojiChoices.map((emoji) => (
                <button
                  type="button"
                  key={emoji}
                  onClick={() => setDraft({ ...draft, emoji })}
                  className={cn(
                    'flex h-10 w-10 items-center justify-center rounded-xl border text-lg transition hover:scale-105',
                    draft.emoji === emoji ? 'border-brand-500 bg-brand-500/10 ring-2 ring-brand-500/20' : '',
                  )}
                  style={{ borderColor: draft.emoji === emoji ? undefined : 'var(--border)' }}
                >
                  {emoji}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="label">{t('description')}</label>
            <textarea className="input min-h-[84px] resize-y" value={draft.description} onChange={(e) => setDraft({ ...draft, description: e.target.value })} placeholder="Mahsulot haqida qisqa ma'lumot..." />
          </div>

          <div className="flex gap-2 pt-1">
            <button type="button" className="btn-secondary flex-1" onClick={() => setModalOpen(false)}>{t('cancel')}</button>
            <button type="submit" className="btn-primary flex-1">{editing ? t('save') : t('addProduct')}</button>
          </div>
        </form>
      </Modal>

      <Modal
        open={!!toDelete}
        onClose={() => setToDelete(null)}
        title={t('delete')}
        subtitle={t('confirmDelete')}
      >
        <div className="flex items-center gap-3 rounded-2xl bg-rose-500/10 p-3">
          <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-rose-500/15 text-xl">{toDelete?.emoji}</span>
          <div>
            <p className="text-sm font-extrabold">{toDelete?.name}</p>
            <p className="text-xs text-[var(--muted)]">{toDelete?.sku}</p>
          </div>
        </div>
        <div className="mt-5 flex gap-2">
          <button className="btn-secondary flex-1" onClick={() => setToDelete(null)}>{t('cancel')}</button>
          <button className="btn flex-1 bg-rose-500 text-white hover:bg-rose-600" onClick={confirmDelete}>{t('delete')}</button>
        </div>
      </Modal>
    </div>
  );
};
